<?php
$eyebrow = get_sub_field( 'eyebrow' ); $heading = get_sub_field( 'heading' ); $description = get_sub_field( 'description' ); $steps = di_service_v2_rows( get_sub_field( 'steps' ) );
$display = 'cards' === get_sub_field( 'display_style' ) ? 'cards' : 'tabs'; $background = get_sub_field( 'background' );
if ( ! $eyebrow && ! $heading && ! $description && ! $steps ) { return; }
$uid = 'seo-process-' . absint( get_the_ID() ) . '-' . absint( get_row_index() );
?>
<section class="work-process-wrp padding_top_bottom service-v2-process service-v2-process--<?php echo esc_attr( $display ); ?> <?php echo esc_attr( di_service_v2_background_class( $background ) ); ?>" id="seo-process">
	<div class="container"><div class="heading text-center"><?php if ( $eyebrow ) : ?><p class="service-v2-kicker"><?php echo esc_html( $eyebrow ); ?></p><?php endif; ?><?php if ( $heading ) : ?><h2><?php echo esc_html( $heading ); ?></h2><?php endif; ?><?php if ( $description ) : ?><div class="sub_pera"><?php echo wp_kses_post( wpautop( $description ) ); ?></div><?php endif; ?></div>
	<?php if ( $steps && 'cards' === $display ) : ?><div class="service-v2-process-cards"><?php foreach ( $steps as $step ) : ?><article><?php if ( ! empty( $step['label'] ) ) : ?><p class="service-v2-kicker"><?php echo esc_html( $step['label'] ); ?></p><?php endif; ?><h3><?php echo esc_html( $step['title'] ?? '' ); ?></h3><?php echo wp_kses_post( wpautop( $step['description'] ?? '' ) ); ?><?php if ( ! empty( $step['image'] ) ) { echo di_infotech_image( $step['image'], 'di-content' ); } ?></article><?php endforeach; ?></div><?php elseif ( $steps ) : ?><div class="row align-items-center"><div class="col-lg-6 col-sm-6"><div class="work-process-tab"><div class="nav flex-column nav-pills" role="tablist"><?php foreach ( $steps as $i => $step ) : ?><h3><button class="nav-link<?php echo 0 === $i ? ' active' : ''; ?>" data-bs-toggle="pill" data-bs-target="#<?php echo esc_attr( $uid . '-' . $i ); ?>" type="button"><?php echo esc_html( ! empty( $step['title'] ) ? $step['title'] : ( $step['label'] ?? '' ) ); ?></button></h3><?php endforeach; ?></div></div></div><div class="col-lg-6 col-sm-6"><div class="tab-content"><?php foreach ( $steps as $i => $step ) : ?><div class="tab-pane fade<?php echo 0 === $i ? ' show active' : ''; ?>" id="<?php echo esc_attr( $uid . '-' . $i ); ?>"><div class="work-process-text"><?php if ( ! empty( $step['image'] ) ) { echo di_infotech_image( $step['image'], 'di-content' ); } ?><div class="main-nav"><p class="bg_yellow"><?php echo esc_html( ! empty( $step['title'] ) ? $step['title'] : ( $step['label'] ?? '' ) ); ?></p></div><div class="sub_pera"><?php echo wp_kses_post( wpautop( $step['description'] ?? '' ) ); ?></div></div></div><?php endforeach; ?></div></div></div><?php endif; ?></div>
</section>
